"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[8053],{3804(e){e.exports=JSON.parse('{"title":"React\uc758 \uc5ed\uc0ac\uc640 \ucca0\ud559","date":"2025-07-15","coverUrl":"/kudzu-based-bench/assets/notion/027c6d94c7b004b7.png","html":"<h1 data-notion-block-id=\\"22ce548d-8a8e-8053-838b-ccaae2f86174\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"22ee548d-8a8e-8027-9c09-d5a984709f52\\" id=\\"22ee548d-8a8e-8027-9c09-d5a984709f52\\">React\uc758 \uc5ed\uc0ac\ub97c \ub530\ub77c\uac00\uba70 React\uc758 \ucca0\ud559\uc744 \uc774\ud574\ud558\uae30</h2><a href=\\"https://playfulprogramming.com/posts/react-history-through-code\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://playfulprogramming.com/posts/react-history-through-code</a><p data-notion-block-id=\\"22ee548d-8a8e-80fc-a9bb-e7c022c61303\\">10000 \ub2e8\uc5b4\ub97c \ub530\ub77c\uac00\uba74\uc11c React\uc758 \uc77c\uad00\ub41c \ucca0\ud559\uc744 JSX\uc640 \ud074\ub798\uc2a4 \ucef4\ud3ec\ub10c\ud2b8, \uadf8 \uc774\ud6c4 Fiber \uc544\ud0a4\ud14d\uccd0\uc640 \uc77c\uad00\uc131 \ubb38\uc81c \ud574\uacb0, \uadf8\ub9ac\uace0 \ub370\uc774\ud130 \ud398\uce6d, SSR\uc758 \ub450 \ub300\uc758 \ucef4\ud4e8\ud130 \ubb38\uc81c\uae4c\uc9c0, \uc2ec\uc9c0\uc5b4 React\uc758 \ubbf8\ub798\ub294 \uc5b4\ub514\ub85c \uac00\uace0 \uc788\ub294\uc9c0\uae4c\uc9c0 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4! \ubb3c\ub860 \ucc98\uc74c\ubd80\ud130 \uc774 \uae00\uc744 \ubaa8\ub450 \uc77d\uae30\ub294 \ud798\ub4e4\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uae00\uc740 React\ub294 \ubcc0\ud558\uc9c0 \uc54a\uace0, \uc77c\uad00\ub41c \ucca0\ud559\uc744 \uac00\uc9c0\uace0 \uc788\uace0(\uc758\uc678\ub85c), \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \\"\uc6b0\ub9ac \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\uba74 \uc131\ub2a5 \ud5a5\uc0c1\uc774 \ub420 \uac70\uc57c\\"\ub77c\ub294 \ubbf8\uc2e0\uacfc \ub2e4\ub974\uac8c, \uc218\ub9ce\uc740 \uc804\ub7b5\uacfc \ub7ec\ub2dd \ucee4\ube0c\ub294 \uc131\ub2a5 \ud5a5\uc0c1\uc758 \ub9cc\ubcd1\ud1b5\uce58\uc57d\uc774 \uc5c6\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4(\ubb3c\ub860 React\ub3c4\uc694!). \uc774\uc804\uc758 \uc88b\uc740 \ub514\uc9c0\ud138 \ucc45\uc778 The Framework Field Guide\uc758 <a href=\\"https://playfulprogramming.com/collections/framework-field-guide-ecosystem\\">\ub450 \ubc88\uc9f8 \ucc45</a>\uc774 \ubc1c\ud589\ub418\uace0 \uc788\uc73c\ub2c8 \uc774 \ucc45\uc744 \ucc38\uace0\ud558\uac70\ub098, Frontendmastery\uc758 <a href=\\"https://frontendmastery.com/posts/the-new-wave-of-javascript-web-frameworks/\\">JS \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uc0c8\ub85c\uc6b4 \ubb3c\uacb0</a>\uc740 \uc774 \uae00\uc744 \uc774\ud574\ud558\uae30\uc5d0 \ub3c4\uc6c0\uc744 \uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"22ce548d-8a8e-8004-92b0-e01a2f3c4f7b\\" id=\\"22ce548d-8a8e-8004-92b0-e01a2f3c4f7b\\">Signals\uc5d0 \ub300\ud55c \uc624\ud574\uc640 \uc9c4\uc2e4</h2><a href=\\"https://www.youtube.com/watch?v=VgGl9i-OBBI\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=VgGl9i-OBBI</a><p data-notion-block-id=\\"22ce548d-8a8e-80c0-9c97-d0176f7ab339\\">Signals\uc758 \uae30\uc6d0\uacfc \uad6c\uc870\uc640 \ud2b9\uc9d5, \uc624\ud574\uc640 \uc9c4\uc2e4\uc744 \ubaa8\ub450 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. hook\uc744 \ub9ce\uc774 \ub9cc\ub4e4\uc5b4\ub0b4\uba74\uc11c \uc783\uc5c8\ub358 React\uc758 \ub2e8\uc21c\ud568\uc744 fine-grained reactivity\ub97c \ud1b5\ud574 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc0dd\ud0dc\uacc4\uc758 \ub113\uc74c\uc740 \ubb34\uc2dc\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c, \uc120\ud0dd\uc740 \ud56d\uc0c1 \uc2e0\uc911\ud558\uac8c \ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. Signals\uc758 \uad6c\uc870\uc640 \ud2b9\uc9d5\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/dac588d9-f575-4eef-b830-f21f1c3fb35d#c29bb324-bded-42b5-8094-a2281c1cb336\\">\ubc18\uc751\uc131\uc758 \uc804\ud30c</a> \uc2dc\ub9ac\uc988 \uae00\uc774 \uc798 \uc124\uba85\ud558\uace0 \uc788\uc73c\ub2c8, \uae00\ub85c \uc77d\uc73c\uc2dc\ub294 \uac83\uc774 \uc88b\uc73c\uc2e0 \ubd84\uc740 \ucc38\uace0\ud558\uc138\uc694. </p><h1 data-notion-block-id=\\"22ce548d-8a8e-80b5-a83d-d4f887a27365\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"22ee548d-8a8e-807f-86b4-f1c2569c9293\\" id=\\"22ee548d-8a8e-807f-86b4-f1c2569c9293\\">\ubc88\ub4e4\ub7ec\uc758 scope hoisting</h2><a href=\\"https://devongovett.me/blog/scope-hoisting.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devongovett.me/blog/scope-hoisting.html</a><p data-notion-block-id=\\"22ee548d-8a8e-802c-8eec-d7d6c47f55d8\\">\ubc88\ub4e4\ub7ec\uc758 scope hoisting\uc758 \uc6d0\ub9ac, \uadf8 \ud55c\uacc4\uc640 \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. code spliting\uacfc scope hoisting\uc774 \uc5b4\ub5bb\uac8c \ucda9\ub3cc\ud558\ub294\uc9c0\uc640 \ucd5c\uc2e0 \ubc88\ub4e4\ub7ec\uc5d0\uc11c\ub294 \uc758\ubbf8\uac00 \uc5c6\ub294 \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \uac83\uc774 \uc778\uc0c1\uc801\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"22ee548d-8a8e-80d8-9f8d-e21fbb55f842\\" id=\\"22ee548d-8a8e-80d8-9f8d-e21fbb55f842\\">i18n \uac1c\ud3b8 \ubcf5\uae30\ud558\uae30</h2><a href=\\"https://www.patreon.com/posts/133137028\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.patreon.com/posts/133137028</a><p data-notion-block-id=\\"22ce548d-8a8e-801e-8521-f88812dfd359\\">pateron\uc758 \uad6d\uc81c\ud654 \ubc29\uc2dd\uc744 \uac1c\ud3b8\ud558\uba74\uc11c \uc798 \ubc88\uc5ed\ub41c i18n \ucee8\ud150\uce20\ub294 \uc5b4\ub54c\uc57c \ud558\ub294\uc9c0\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uadf8 \uc774\uc678\uc5d0\ub3c4 i18n \uc774\uc678\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub294, \uc6f9 \ud45c\uc900 \uc0ac\uc6a9\uc5d0 \ub300\ud55c \uc758\uacac, \uae30\uc874 \ucf54\ub4dc\ub97c \uc5b4\ub5bb\uac8c \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud588\ub294\uc9c0\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"22ee548d-8a8e-80ac-8dbe-cc7e7d363e0e\\" id=\\"22ee548d-8a8e-80ac-8dbe-cc7e7d363e0e\\">\ud06c\ub85c\uc2a4 \ud50c\ub7ab\ud3fc(\ubaa8\ub4e0 OS) \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc758 \uadfc\ud669</h2><a href=\\"https://www.paisanos.io/blog/the-universal-way-one-codebase-all-platforms\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.paisanos.io/blog/the-universal-way-one-codebase-all-platforms</a><p data-notion-block-id=\\"22ee548d-8a8e-805f-970c-c0e59561c6ef\\">RN \uae30\ubc18 \ud06c\ub85c\uc2a4 \ud50c\ub7ab\ud3fc(Android, iOS \uc678\uc5d0\ub3c4!) \uc0dd\ud0dc\uacc4\ub294 \uc5b4\ub5bb\uac8c \uad6c\uc131\ub418\uc5b4\uac00\uace0 \uc788\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \uc7a5\ub2e8\uc810\uc774 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"22ce548d-8a8e-808a-ae9e-fce2f83846ef\\" id=\\"22ce548d-8a8e-808a-ae9e-fce2f83846ef\\">satisfies\ub294 \uc5b4\ub514\uc5d0 \uc4f0\ub294 \ubb3c\uac74\uc77c\uae4c</h2><a href=\\"https://frontendmasters.com/blog/satisfies-in-typescript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/satisfies-in-typescript/</a><p data-notion-block-id=\\"22ee548d-8a8e-8042-abfe-f922d9eeb4b6\\"><code>as</code>\ub294 \ud0c0\uc785\uc744 \uac15\uc81c \uc9c0\uc815\ud558\uc5ec \ubc14\uafd4\uc8fc\uc9c0\ub9cc, <code>satisfies</code>\ub294 \ud0c0\uc785 \uc548\uc815\uc131\uc744 \ub192\uc5ec\uc90d\ub2c8\ub2e4. \uc774\ub97c \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ud558\uba74 \uc88b\uc744\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"22ce548d-8a8e-8098-9e32-d17aeaa509da\\" id=\\"22ce548d-8a8e-8098-9e32-d17aeaa509da\\">RSC\ub294 \uc5b4\ub5bb\uac8c \ud14c\uc2a4\ud2b8\ud558\ub098\uc694</h2><a href=\\"https://www.nico.fyi/blog/how-to-test-react-server-component\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nico.fyi/blog/how-to-test-react-server-component</a><h2 data-notion-block-id=\\"22ee548d-8a8e-80d8-b28d-d49c385d26ec\\" id=\\"22ee548d-8a8e-80d8-b28d-d49c385d26ec\\">\uac1c\ubc1c\ub3c4\uad6c \ub79c\ub529\ud398\uc774\uc9c0\ub294 \ubcf4\ud1b5 \uc5b4\ub5bb\uac8c \uad6c\uc131\ub418\ub098\uc694</h2><a href=\\"https://evilmartians.com/chronicles/we-studied-100-devtool-landing-pages-here-is-what-actually-works-in-2025\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://evilmartians.com/chronicles/we-studied-100-devtool-landing-pages-here-is-what-actually-works-in-2025</a><h2 data-notion-block-id=\\"22ee548d-8a8e-801c-b02d-fbe7542bca97\\" id=\\"22ee548d-8a8e-801c-b02d-fbe7542bca97\\">React\uc758 \uc0c1\ud0dc\ub9cc\uc758 \ud2b9\uc9d5 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://www.56kode.com/posts/level-up-react-deep-dive-into-state-and-usestate/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.56kode.com/posts/level-up-react-deep-dive-into-state-and-usestate/</a><h2 data-notion-block-id=\\"22ee548d-8a8e-8045-b906-e189d9b4d351\\" id=\\"22ee548d-8a8e-8045-b906-e189d9b4d351\\">React Three Fiber\ub85c \ud0a4\ub124\ud2f1 \uc774\ubbf8\uc9c0 \ub80c\ub354\ub9c1 \uad6c\ud604\ud558\uae30</h2><a href=\\"https://tympanus.net/codrops/2025/07/09/how-to-create-kinetic-image-animations-with-react-three-fiber/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tympanus.net/codrops/2025/07/09/how-to-create-kinetic-image-animations-with-react-three-fiber/</a><h1 data-notion-block-id=\\"22ce548d-8a8e-8088-873b-c6cb0dc366bd\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://github.com/vitejs/vite-plugin-react/issues/531\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/vitejs/vite-plugin-react/issues/531</a><p data-notion-block-id=\\"22ee548d-8a8e-80e3-93d2-cd16dbaf453f\\"><code>@vitejs/plugin-rsc</code>\uac00 \ubc30\ud3ec\ub418\uc5c8\uace0, Vite\ub97c \ud1b5\ud55c RSC \uc0ac\uc6a9\uc774 \uc5b4\ub5bb\uac8c \ub420\uc9c0 \uc9c0\ucf1c\ubd10\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://rspack.rs/blog/announcing-1-4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rspack.rs/blog/announcing-1-4</a><p data-notion-block-id=\\"22ce548d-8a8e-80c2-abf7-e0e61ace436e\\">rspack 1.4\uc5d0\uc11c \ube0c\ub77c\uc6b0\uc800\ub85c \ube4c\ub4dc\ud558\ub294 \uae30\ub2a5, SWC\ub85c \uc18d\ub3c4 \uc0c1\uc2b9\u2026. \ub4f1 \uc5ec\ub7ec\uac00\uc9c0 \uae30\ub2a5\uc744 \ub9b4\ub9ac\uc988\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://devblogs.microsoft.com/typescript/announcing-typescript-5-9-beta/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/typescript/announcing-typescript-5-9-beta/</a><p data-notion-block-id=\\"22ee548d-8a8e-80e9-8320-ff4f31a1295b\\">ECMAScript \uc0c8 \uae30\ub2a5\uacfc \uc5ec\ub7ec \uc720\ud2f8 \uae30\ub2a5\uc744 \ucd94\uac00\ud55c TypeScript 5.9 beta \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://www.electronjs.org/blog/electron-37-0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.electronjs.org/blog/electron-37-0</a><p data-notion-block-id=\\"22ee548d-8a8e-80e7-bd06-dbf83e251a3f\\">\uc77c\ub809\ud2b8\ub860 37\uc774 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://socket.dev/blog/browserslist-rs-gets-major-optimization\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://socket.dev/blog/browserslist-rs-gets-major-optimization</a><p data-notion-block-id=\\"231e548d-8a8e-802f-ab3f-c9b95d75d37d\\">browserlist\uac00 rust\ub85c \uad6c\ud604\ub41c browserlist-rs\uc758 \ud06c\uae30 \uc0ac\uc774\uc988\uac00 \uc904\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p>"}')}}]);